firmware:
const int RED = 25, YELLOW = 26, GREEN = 27;
int cycles = 0;

void only(int pin) {
  digitalWrite(RED, pin == RED);
  digitalWrite(YELLOW, pin == YELLOW);
  digitalWrite(GREEN, pin == GREEN);
}

void setup() {
  Serial.begin(115200);
  pinMode(RED, OUTPUT);
  pinMode(YELLOW, OUTPUT);
  pinMode(GREEN, OUTPUT);
}

void loop() {
  only(RED);
  delay(1000);
  only(GREEN);
  delay(1000);
  only(YELLOW);
  delay(500);
  if (++cycles == 1) Serial.println("CYCLE");
}
